"// lastNamePrefix field mapping
// Description: Last name prefix - filled conditionally based on name convention (Person.Name.Convention). 
// Medicore displays: [partnerName] [lastName]. 
// Convention B (Own): lastNamePrefix=own prefix.
// Convention PB (Partner-Own): lastNamePrefix=own prefix.
// Convention P (Partner): lastNamePrefix=partner prefix.
// Convention BP (Own-Partner): lastNamePrefix=partner prefix.

function getLastNamePrefix() {
    const convention = Person.Name.Convention;
    const ownPrefix = Person.Name.FamilyNamePrefix;
    const partnerPrefix = Person.Name.FamilyNamePartnerPrefix;

    // Convention: B/PB = own prefix, P/BP = partner prefix
    switch(convention) {
        case 'B':
        case 'PB':
            return ownPrefix || '';
        case 'P':
        case 'BP':
            return partnerPrefix || '';
        default:
            return ownPrefix || '';
    }
}

getLastNamePrefix();"

"// partnerName field mapping
// Description: Partner name - filled conditionally based on name convention (Person.Name.Convention). 
// Medicore displays: [partnerName] [lastName], so partnerName is shown FIRST. 
// Convention B (Own): partnerName=empty.
// Convention P (Partner): partnerName=empty.
// Convention BP (Own-Partner): partnerName=own name.
// Convention PB (Partner-Own): partnerName=partner name.

function getPartnerName() {
    const convention = Person.Name.Convention;
    const ownName = Person.Name.FamilyName;
    const partnerName = Person.Name.FamilyNamePartner;

    // Convention: B/P = Single name (no partnerName field), BP = own name, PB = partner name
    switch(convention) {
        case 'BP':
            // Own-Partner: partnerName=own, lastName=partner → display "own partner"
            return ownName || '';
        case 'PB':
            // Partner-Own: partnerName=partner, lastName=own → display "partner own"
            return partnerName || '';
        default:
            // Single name conventions: no partnerName needed
            return '';
    }
}

getPartnerName();"

